import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Navbar from "./components/navbar/Navbar";

import HomePage from "./pages/student/HomePage/HomePage.jsxx";
import EventDirectory from "./pages/student/EventDiscovery/EventDiscovery.jsx";
import MyEvents from "./pages/student/MyEvents/MyEvents.jsx";
import AboutUs from "./pages/student/AboutUs/AboutUs.jsx";
import ProfilePage from "./pages/student/ProfilePage/ProfilePage.jsx";

function App() {
  return (
    <Router>
      <Navbar />
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/directory" element={<EventDirectory />} />
        <Route path="/myevents" element={<MyEvents />} />
        <Route path="/aboutus" element={<AboutUs />} />
        <Route path="/profile" element={<ProfilePage />} />
      </Routes>
    </Router>
  );
}

export default App;
